[
  {
    "hypothesis_id": 34,
    "feature": {
      "name": "op_argument_has_explicit_uncertainty",
      "dtype": "binary",
      "source_columns": [
        "argument"
      ],
      "definition": "OP argument text (post body, current text incl. marked edits; excluding quotations of others): 1 if the OP expresses explicit uncertainty markers about their own view or claims, else 0",
      "kind": "prompt",
      "spec": "Read the 'argument' column (OP's post body, current text including marked edits). Output 1 if the OP, in their own voice, explicitly marks uncertainty about their own view or claims (e.g. 'I'm not sure', 'I might be wrong', 'maybe', 'I could be mistaken', 'to my knowledge', 'I don't know whether'). Output 0 if no such explicit marker appears. Ignore quoted text from others, reported opponents' positions, and moderator/bot notices unless the OP adopts them as their own uncertainty. Generic hedging words not signalling uncertainty about the OP's own stance do not count; absolute certainty is not required for 0 beyond absence of markers. Do not use title, comments or other columns. Return null if argument is missing or empty/malformed."
    }
  },
  {
    "hypothesis_id": 53,
    "feature": {
      "name": "op_argument_uses_hedging",
      "dtype": "binary",
      "source_columns": [
        "argument"
      ],
      "definition": "OP argument text (post body, current text incl. marked edits; excluding quoted external text): 1 if the OP uses hedging or qualifying language in their own assertions",
      "kind": "prompt",
      "spec": "Read the 'argument' column only. Return 1 if the OP, in their own voice, uses hedging or qualifying language that softens or limits the strength of a claim (e.g. 'I think', 'maybe', 'perhaps', 'in most cases', 'might', 'to my knowledge', 'generally'); these are nonexhaustive examples. Ignore hedges inside quotations of others or in non-claim text. Use the current text including marked edits. Return 0 if the argument is assessable and has no such language. Return null if argument is missing or empty/malformed."
    }
  }
]

